import{Mt as e,ft as t,mt as n,n as r}from"./chunks/framework.CLZVGDxv.js";import{ai as i,ei as a,ni as o}from"./chunks/assets.D5yHj6gx.js";var s=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"en/link.md","filePath":"en/link.md"}`),c={name:`en/link.md`};function l(r,s,c,l,u,d){return e(),t(`div`,null,[...s[0]||=[n(`<h2 id="ai-yinmei-information" tabindex="-1">AI Yinmei Information <a class="header-anchor" href="#ai-yinmei-information" aria-label="Permalink to “AI Yinmei Information”">​</a></h2><ul><li><strong>AI Name：</strong> Yinmei</li><li><strong>Developer：</strong> Winlone</li><li><strong>Bilibili Channel：</strong> <a href="https://space.bilibili.com/46130941" target="_blank" rel="noreferrer">Programmer&#39;s Retirement Life</a></li><li><strong>Live Stream：</strong> <a href="http://live.bilibili.com/3033646" target="_blank" rel="noreferrer">Click to enter</a></li><li><strong>Technical QQ Group：</strong> 27831318</li><li><strong>Fan Group：</strong> 264534845</li><li><strong>Version：</strong> 3.0.0-Pre</li><li><strong>Open Source：</strong> <a href="https://github.com/worm128/AI-YinMei" target="_blank" rel="noreferrer">Click to enter</a></li></ul><h2 id="download-the-software" tabindex="-1">Download the software <a class="header-anchor" href="#download-the-software" aria-label="Permalink to “Download the software”">​</a></h2><p><a href="https://hub.docker.com/r/worm128/yinmei-core" target="_blank" rel="noreferrer">Docker</a> | <a href="https://pan.baidu.com/s/11kIws0H0YITmwVucqoCWrA?pwd=6e74" target="_blank" rel="noreferrer">Windows</a> | <a href="https://pan.baidu.com/s/11kIws0H0YITmwVucqoCWrA?pwd=6e74" target="_blank" rel="noreferrer">Linux</a></p><h2 id="project-download" tabindex="-1">Project Download <a class="header-anchor" href="#project-download" aria-label="Permalink to “Project Download”">​</a></h2><ul><li><strong>Yinmei Integration Package Download Address：</strong><br> Baidu Netdisk Group: Please add the group number in &quot;Baidu Netdisk -&gt; Messages&quot; Baidu Netdisk Group 1: 930109408 (Full) Baidu Netdisk Group 2: 939447713 (Full) Baidu Netdisk Group 3: 945900295 Baidu Netdisk Group 4: 969208563</li><li><strong>Quark：</strong><br> Quark Group 1: 1231405830 Quark Group 2: 428937868</li><li><strong>Functional Integration Package Downloads (6)：</strong> Artificial Intelligence -&gt; yinmei-all Desktop Pet 2.0 yinmei-desktop-plus, TTS Speech Synthesis GPT-SoVITS-Versions 1.0 and 2.0, Pornography Detection public-NSFW-y-distinguish, Painting stable-diffusion-webui, Live2D Skin</li><li><strong>Yinmei Core [Version Iteration]：</strong> Artificial Intelligence -&gt; Yinmei Core Yinmei Development Documentation: Artificial Intelligence -&gt; Yinmei Development Documentation</li></ul><h2 id="integration-package-contents" tabindex="-1">Integration Package Contents <a class="header-anchor" href="#integration-package-contents" aria-label="Permalink to “Integration Package Contents”">​</a></h2><p>Path: Artificial Intelligence -&gt; Yinmei Core. Select a core version to download, usually the latest version. <img src="`+i+`" alt="down-yinmei.png" width="581" height="596"></p><p>Path: Artificial Intelligence -&gt; yinmei-all<br><img src="`+o+`" alt="other-software.png" width="2588" height="1633"></p><h2 id="function-overview" tabindex="-1">Function Overview <a class="header-anchor" href="#function-overview" aria-label="Permalink to “Function Overview”">​</a></h2><ul><li><strong>Aggregated Bullet Comments:</strong> Aggregates live stream bullet comments, supporting the display of bullet comments from 9 major sources including Bilibili development platform, Napcat [QQ robot], Barragefly [Douyin, Huya, Kuaishou, Douyu], WeChat live stream, desktop pets, and background chat dialogues.</li><li><strong>Intent Analysis:</strong> Intent analysis with a 10ms response time can be used to train corpora to increase intent classification. Currently, it uses a multi-head attention mechanism, which can simultaneously analyze intent classification and sentiment classification.</li><li><strong>Large Model Tools:</strong> Supports MCP tools and custom-written code tools. Tools include: camera observation, timed patrol, visual capabilities, image search, greeting functionality, Wikipedia, TMDB movie rating website, browser manipulation, calculator, user points query, advanced search, thought chain, product information query, stock tools, time zone conversion, random number generation, cooking guide, changing character clothing, character movement and rotation, video search and playback, speech synthesis switch, speech speed adjustment, AI video, AI singing, AI painting, search tools, and 27 other tools.</li><li><strong>Lottery:</strong> The lottery is divided into self-service lotteries and streamer lotteries. Self-service lotteries are initiated by users entering &quot;lottery&quot; in the chat, while streamer lotteries are conducted by the streamer who clicks the lottery button to draw prizes from all online users in the live stream. Features include a list of lottery prizes and lottery records.</li><li><strong>Long-term memory:</strong> Intelligently recalls memories from different time periods based on time pronouns. It selectively recalls memories, avoiding impacting the main workflow speed by activating memories every time. The number of times a memory is recalled, its similarity, etc., can be set.</li><li><strong>Short-term memory:</strong> Recorded in the large model context memory of the MongoDB database, all chat records are fully persisted.</li><li><strong>Points:</strong> Each user earns points for chatting, liking, sending gifts, and registering. Singing, drawing, playing videos, switching songs, and participating in raffles will deduct points. Points configuration options are available.</li><li><strong>Diffusion Thinking:</strong> Using the graph relation database neo4j to construct word relationships, you can export q-group data for thinking relationship training, and the analyzed graph will be displayed in neo4j.</li><li><strong>Chat:</strong> Supports all cloud service providers and local services that meet the OpenAI specification, with 100% coverage of large LLM models. LLM is streamed for high-performance dialogue.</li><li><strong>Voice Support:</strong> Supports Cosyvoice2, Bert-Vits2, the entire GPT-Sovits series, and Edge-TTS. OpenAI-compliant TTS is supported by 80% of TTS cloud providers on the market. Cosyvoice2 has been significantly modified and tweaked for tone and emotion, and VLLM acceleration has been implemented, making it stronger and faster than other speech synthesizers on the market. Voice is streamed for high-performance TTS.</li><li><strong>Vision:</strong> Supports OpenAI-compliant data models and visual models from most cloud vendors.</li><li><strong>Camera:</strong> Supports multi-camera monitoring and analysis</li><li><strong>Computer Control:</strong> Supports the computer to autonomously control the keyboard and mouse based on screen analysis.</li><li><strong>Live Streaming UI Plugins:</strong> Supports 18 UI plugins to assist with live streaming.</li><li><strong>Knowledge Base:</strong> Currently using FastGPT knowledge base capabilities for knowledge management and loading.</li><li><strong>Singing:</strong> It can cover songs in any language. It takes about 150 to 200 seconds to learn a song. The singing model can train its own tone.</li><li><strong>Painting:</strong> Supports downloading any painting model from civitai.com for drawing.</li><li><strong>Image Search:</strong> Use Baidu search to search for images.</li><li><strong>Search:</strong> Use the search aggregation platform searchng, which includes search engines such as Google, Bing, duckduckgo, Wikipedia, startpage, and brave. Requires a VPN.</li><li><strong>Characters:</strong> Supports the self-developed Yinmei desktop pet and Vtube Studio [available for download on Steam or the product&#39;s cloud drive]. The Yinmei desktop pet comes with a built-in microphone, powerful noise reduction, VAD, and AEC capabilities, and is overlaid with a voiceprint system, ensuring real-time conversations without accidental touches.</li><li><strong>Emojis:</strong> There are emoji schemes that can control character expressions, supporting the playback of character expressions + sound effects + video, supporting loop playback and random playback, and keyword-triggered emojis.</li><li><strong>Videos:</strong> Can play any video within a local folder, and supports videos stored in subfolders. Supports pulling and playing videos from Bilibili.</li><li><strong>NSFW:</strong> Supports image content moderation, can filter illegal characters in comments, provides AI responses to illegal characters, and draws prompts for illegal words.</li><li><strong>Other:</strong> Supports off-peak tasks, supports welcome messages upon entering a room, supports intelligent installation of Docker services, supports server monitoring, and supports data statistics.</li></ul><h2 id="command-description" tabindex="-1">Command Description <a class="header-anchor" href="#command-description" aria-label="Permalink to “Command Description”">​</a></h2><p><strong>1. Basic Commands:</strong><br> 1.1 Add &quot;&quot; (e.g., &quot;\\I&#39;m chatting in the live broadcast room&quot;) so the AI won&#39;t reply to user content</p><p><strong>2. Singing Function:</strong></p><p>2.1 Enter &quot;sing&quot; + song title, and Yinmei will learn to sing based on the song title you entered. You can also enter open-ended questions like &quot;Yinmei, recommend me the best anime song,&quot; and Yinmei will intelligently select a song for you to sing.</p><p>2.2 To change songs, enter &quot;Cut Song&quot; to skip the current song and start learning the next one.</p><p>2.3 Enter &quot;Stop Learning Song,&quot; and Yinmei will terminate the current song and move on to the next one.</p><p><strong>3. Drawing Function:</strong></p><p>3.1 Enter &quot;draw&quot; + picture title, and Yinmei will draw in real time based on the drawing prompt you enter.</p><p>3.2 You can also enter open-ended questions like &quot;Yinmei, draw me the ugliest little turtle egg,&quot; and Yinmei will intelligently generate drawing prompts for you to draw.</p><p><strong>4. Video Playback:</strong></p><p>4.1 Enter &quot;video + dance name&quot;. Dances are as follows:</p><p>Video files must be locally configured.</p><p>Secretary Dance, Subject Three, Girl Group Dance, Social Dance</p><p>Guagua Dance, Ma Baoguo, Anime, Sese</p><p>Cai Xukun, Gangnam Style, Chipi, Yinmei</p><p>Directly entering &quot;video&quot; will create a random dance.</p><p>4.2 To stop the dance, enter &quot;Stop Video.&quot;</p><p><strong>5. Emoji:</strong></p><p>Enter &quot;emoji + name.&quot; &quot;emoji + random&quot; will create a random emoji. You can guess the emoji yourself, for example, &quot;crying, laughing, sticking out tongue.&quot;</p><p><strong>6. Scene Switching:</strong></p><p>6.1 Enter &quot;Switch + Scene Name&quot;: Pink Room, Shrine, Coastal Flower Shop, Flower Room, Morning Room.</p><p>6.2 The system intelligently determines the time to switch between morning and evening scenes.</p><p><strong>7. Dress-Up:</strong></p><p>Enter &quot;Outfit + Outfit Name&quot;: Plain Clothes, Wings of Love, Youthful Cat Girl, Glasses Cat Girl.</p><p><strong>8. Image Search:</strong><br> Enter &quot;search image + keyword&quot;</p><p><strong>9. Information Search Function:</strong><br> Enter &quot;search + keyword&quot;</p><h2 id="technical-architecture" tabindex="-1">Technical Architecture <a class="header-anchor" href="#technical-architecture" aria-label="Permalink to “Technical Architecture”">​</a></h2><p><img src="`+a+`" alt="Yinmei Flowchart 2.4.2.png" width="4269" height="3422"></p>`,39)]])}var u=r(c,[[`render`,l]]);export{s as __pageData,u as default};